s=open('rev13_edit.py',encoding='utf-8-sig').read()
def rep(a,b,c=1):
    global s
    assert s.count(a)==c,(a[:60],s.count(a)); s=s.replace(a,b)
# 22b opening: move packing scene in, fix timing
rep("B22b='''## 22b Reason for Return\n\nAt eight that evening Miriam went down","B22b='''## 22b Reason for Return\n\nThey went to the registry to pack the documents. Arthur followed with Hester’s account. He described the printer carefully: the way she asked for payment before accepting explanations, the damage to Daniel’s hand, her distrust of unsolicited rescue. Beatrice listened with the attention of someone learning the terms of an important appointment.\n\n“Don’t promise to rebuild her shop,” Arthur said. “We need to make actual arrangements, not leave her with gratitude.”\n\n“I’ve included specie and a written authorisation for compensation.”\n\n“From whom?”\n\n“Me.”\n\nHe waited.\n\n“I have savings, Mr Pembroke. It has been an uneventful nineteen years in some respects.”\n\nHe did not argue. She was paying for a broken press; absolution did not come into it.\n\nAt half past ten that night Miriam went down")
rep("d.cutrange(\"At eight that evening Miriam went down to Records\",","d.cutrange(\"They went to the registry to pack the documents.\",")
rep("and the one we are going to break tomorrow.","and the one we are going to break in the morning.")
rep("“I’m going to 2029 tomorrow. I’m going","“I’m going to 2029 in a few hours. I’m going")
rep("Beatrice did not answer. Neither of them reached","“Eleanor ruled a column on Monday,” Beatrice said. “I have been through my fifty-three since. Fifty-two I can explain. Strangers, mostly, and a canal. I did not need to be told which one I couldn’t.”\n\n“*Retained as drafted*,” Miriam said. “I have read the constitution of a government that hasn’t happened yet, and that is the most frightening phrase in it.”\n\n“It is a very ordinary phrase. That is what is frightening about it.”\n\nBeatrice did not answer. Neither of them reached")
# the earlier slip: 'Miriam looked at the receipt... It was true twice' must precede; reorder so 'true twice' comes before the column beat
rep("Miriam looked at the receipt again. “Reason for return. Personal.”\n\n“Yes.”\n\n“It was true twice.”\n\n“Eleanor ruled","Miriam looked at the receipt again. “Reason for return. Personal.”\n\n“Yes.”\n\n“It was true twice.”\n\n“Eleanor ruled")
# 34b: setting beats and Eleanor
rep("Glock sat behind a plain table. Without the excellent coat","The visitors’ room had a vending machine, which offered tea in three varieties of the same tea. Arthur did not press anything. It had been that kind of year.\n\nGlock sat behind a plain table. Without the excellent coat")
rep("Arthur found this more disturbing than if prison had transformed him into a visibly different kind of person.\n\n“You have won","Arthur found this more disturbing than if prison had transformed him into a visibly different kind of person. He did not offer tea. There was none to offer.\n\n“You have won")
rep("The custody officer asked at the gate whether he had got what he came for.\n\n“No,” Arthur said. “I got what he had been keeping.”","The custody officer asked at the gate whether he had got what he came for.\n\n“No,” Arthur said. “I got what he had been keeping.”\n\nEleanor was waiting in the car park. She had been told, correctly, that she should not attend, and had come anyway to be somewhere near it. He told her in the order Glock had told him. She listened without interrupting, which she did only when it mattered, and at the end she looked at her wrists.\n\n“I would have said the machine leaves no forwarding address,” she said.\n\n“It doesn’t. A woman does.”\n\nShe unbuckled the left watch, looked at it for a moment, and put it in her coat pocket. “I’ll find it a drawer,” she said.")
